import {writingStandardSpec,writingStandardFields} from './writing-standard.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function writingStandardPanel(kind,data,{compact=false}={}){
 const spec=writingStandardSpec(kind);if(!spec)return '';
 const fields=writingStandardFields(kind),selected=data[fields.template],metadata=data[fields.metadata]||{},name='通用'+spec.title+'模板';
 const coverFields=kind==='article'?[['institution','作者单位'],['author','作者']]:kind==='quick'?[['author','作者']]:[['institution','学校'],['college','学院'],['author','姓名'],['studentId','学号'],['supervisor','指导教师']];
 return `<section class="wf-proposal-standard" data-wf-standard ${kind==='proposal'?'data-wf-proposal-standard':''}><div class="wf-standard-heading"><div><span class="wf-kicker">${spec.title}规范</span><h3>${esc(selected?.source?.name||name)}</h3><p class="wf-muted">${compact?'本次写作与导出使用同一份要求。':'先确定'+spec.authority+'要求，再生成提纲和正文；模板示例不会作为研究事实。'}</p></div>${compact?'<button type="button" class="btn secondary" data-wf-standard-edit>修改模板与要求</button>':''}</div>${compact?'':`<div class="wf-actions"><button type="button" class="btn secondary" data-wf-template-choose>${selected?'替换':'上传'}${spec.upload}模板</button><button type="button" class="btn secondary" data-wf-template-stored>从文件管理选择</button><button type="button" class="btn secondary" data-wf-template-download>下载${name}</button>${selected?'<button type="button" class="btn secondary" data-wf-template-reset>使用通用模板</button>':''}</div><input type="file" data-template-file data-no-file-library accept=".docx" hidden><p class="wf-muted" data-template-status role="status">模板支持 DOCX，最大 2MB；保留明确的正文区域或独立的 {{正文}} 占位符。</p><details class="wf-drawer"><summary>${kind==='article'||kind==='quick'?'作者信息':'文档封面信息'}（按实际要求填写）</summary><div class="wf-field-grid">${coverFields.map(([key,label])=>`<label class="wf-field"><span>${label}（可选）</span><input data-wf-cover="${key}" value="${esc(metadata[key]||'')}" maxlength="100"></label>`).join('')}</div><p class="wf-muted">用于填写模板已识别的栏目，不发送给写作模型。</p></details><label class="wf-field"><span>${spec.authority}补充要求（可选）</span><textarea data-wf-field="${fields.requirements}" rows="3" maxlength="3000" placeholder="如栏目顺序、篇幅、引用格式、交付要求等。">${esc(data[fields.requirements]||'')}</textarea></label>${selected?`<details class="wf-drawer"><summary>已读取的模板文字与栏目（可核对）</summary><textarea data-wf-field="${fields.templateText}" rows="6" maxlength="6000">${esc(data[fields.templateText]||'')}</textarea><p class="wf-muted">只作为结构与填写要求使用；示例、签名与评审意见不会自动成为正文事实。</p></details>`:''}<details class="wf-drawer"><summary>${spec.title}撰写要点与规范参考</summary><dl class="wf-standard-guide">${spec.guidance.map(([title,text])=>`<dt>${esc(title)}</dt><dd>${esc(text)}</dd>`).join('')}</dl><p class="wf-muted">具体要求以${spec.authority}当前规定为准。通用模板不代替官方表格或投稿模板。</p>${spec.sources.map(([title,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`).join('<br>')}</details>`}</section>`;
}
